      (EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.category_id, EXCLUDED.region, EXCLUDED.kcal_per_serving,
       EXCLUDED.protein_per_serving, EXCLUDED.carbs_per_serving, EXCLUDED.fat_per_serving, EXCLUDED.image_url);
